#!/usr/bin/env python3
"""Render docs/observability/metric-registry.md: every metric this service
emits, from three sources of truth.

  * The Platform Observability Registry shipped with the pinned
    platform-gincommon (internal/obsregistry/registry.json): every Tier 1
    metric owned by a platform library this service links (platform-gincommon
    HTTP server, platform-events consumer, platform-pgcommon), and the Tier 2
    iam_* entries.
  * A real /metrics scrape (test/unit TestMetrics_ScrapeValidatesAgainstRegistry,
    which records one sample on every collector this service owns): the
    Tier 2 metrics actually emitted and every Tier 3 iam_audit_log_* metric
    with its type, labels and help text.
  * internal/adapter/outbound/metrics/registry.go (PlatformRegistry): the
    Tier 1 names this service builds itself and records into.

Usage: metrics-inventory.py <registry.json> <scrape.txt> <gincommon-version> <registry.go>
Writes the Markdown to stdout. Run through `make metrics-inventory`; CI
fails when the committed file differs (.github/scripts/metricslint.sh).
"""
import json
import re
import sys

SERVICE = "iam-audit-log"
SERVICE_PREFIX = "iam_audit_log_"
LIBRARIES = ("platform-gincommon", "platform-events", "platform-pgcommon")
# No gRPC server in this service.
NOT_EMITTED = ("platform_grpc_",)
# Series-level labels that are not part of a metric's own label set.
IGNORED_LABELS = {"domain", "service", "environment", "le", "quantile"}


def md(text):
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def parse_scrape(path):
    """Return {family: {"type", "help", "labels"}} from Prometheus text."""
    families = {}
    for line in open(path, encoding="utf-8"):
        line = line.rstrip("\n")
        if line.startswith("# HELP "):
            name, _, help_text = line[len("# HELP "):].partition(" ")
            families.setdefault(name, {"labels": set()})["help"] = help_text
        elif line.startswith("# TYPE "):
            name, _, mtype = line[len("# TYPE "):].partition(" ")
            families.setdefault(name, {"labels": set()})["type"] = mtype
        elif line and not line.startswith("#"):
            m = re.match(r"([a-zA-Z_:][a-zA-Z0-9_:]*)(\{([^}]*)\})?", line)
            if not m:
                continue
            series = m.group(1)
            family = series
            for suffix in ("_bucket", "_sum", "_count"):
                if series.endswith(suffix) and series[: -len(suffix)] in families:
                    family = series[: -len(suffix)]
            labels = re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)="', m.group(3) or "")
            families.setdefault(family, {"labels": set()})["labels"].update(
                label for label in labels if label not in IGNORED_LABELS
            )
    return families


def service_built(registry_go):
    """Names in registry.go's PlatformRegistry block."""
    text = open(registry_go, encoding="utf-8").read()
    m = re.search(r"var PlatformRegistry = \[\]RegistryEntry\{(.*?)\n\}", text, re.DOTALL)
    return set(re.findall(r'Name:\s*"([^"]+)"', m.group(1))) if m else set()


def labels_cell(entry):
    labels = entry.get("labels") or []
    if not labels:
        return "-"
    cell = ", ".join(f"`{label}`" for label in labels)
    for label, values in sorted((entry.get("label_values") or {}).items()):
        cell += f"<br>`{label}` ∈ " + ", ".join(f"`{v}`" for v in values)
    return cell


def type_cell(entry):
    mtype = entry.get("type", "")
    if mtype == "histogram" and entry.get("buckets"):
        return f"histogram ({entry['buckets']})"
    return mtype


def main():
    registry_path, scrape_path, gincommon_version, registry_go = sys.argv[1:5]
    registry = json.load(open(registry_path, encoding="utf-8"))
    scrape = parse_scrape(scrape_path)
    built = service_built(registry_go)
    entries = registry["metrics"]

    out = []
    w = out.append
    w(f"# Metric inventory: {SERVICE}")
    w("")
    w("<!-- Generated by `make metrics-inventory` (.github/scripts/metrics-inventory.py) from the")
    w(f"     Platform Observability Registry in platform-gincommon {gincommon_version} and a real /metrics")
    w("     scrape of this service. Do not edit; CI fails when this file is out of date. -->")
    w("")
    w("Every series carries the centrally injected const labels `domain` (`iam`), `service` "
      f"(`{SERVICE}`) and `environment`. The tables list each metric's own labels only. "
      "Status is the registry's: `approved`, or `proposed` (awaiting observability-governance "
      "ratification). Tier 3 metrics are this service's own and need no registry entry. "
      "See [README.md](README.md) for how the tiers are built and enforced.")
    w("")

    w("## Tier 1: platform-shared metrics (emitted by the platform libraries)")
    w("")
    w("The libraries record these on the shared registry (`gincommon.MetricsRegisterer()`). "
      "Metrics marked *service-built* are constructed by this service from the registry "
      "(`gincommon.NewShared*Vec`, `registry.go` `PlatformRegistry`) before platform-events "
      "registers, so the library adopts the same collector and both record into one series set. "
      "platform-events registers its publisher and outbox collectors in every process; here they "
      "stay at zero, because this service publishes nothing (AL-INV-10).")
    w("")
    w("| Metric | Emitted by | Type | Status | Labels | Meaning |")
    w("|---|---|---|---|---|---|")
    for entry in entries:
        if entry.get("tier") != "platform" or entry.get("owner") not in LIBRARIES:
            continue
        if entry["name"].startswith(NOT_EMITTED):
            continue
        owner = entry["owner"] + (", *service-built*" if entry["name"] in built else "")
        w(f"| `{entry['name']}` | {owner} | {type_cell(entry)} | {entry.get('status', '')} "
          f"| {labels_cell(entry)} | {md(entry.get('help'))} |")
    w("")

    w("## Tier 2: IAM domain-shared metrics (emitted by this service)")
    w("")
    w("Built from the registry with `gincommon.NewSharedCounterVec` "
      "(`internal/adapter/outbound/metrics/business.go`, `buildCollectors`), so the name, help, "
      "labels and buckets are the registry's.")
    w("")
    w("| Metric | Type | Status | Labels | Meaning |")
    w("|---|---|---|---|---|")
    for entry in (e for e in entries if e.get("tier") == "domain" and e["name"] in scrape):
        w(f"| `{entry['name']}` | {type_cell(entry)} | {entry.get('status', '')} "
          f"| {labels_cell(entry)} | {md(entry.get('help'))} |")
    w("")
    others = [e["name"] for e in entries if e.get("tier") == "domain" and e["name"] not in scrape]
    if others:
        w("Registered for the `iam` domain but not emitted by this service: "
          + ", ".join(f"`{name}`" for name in others) + ".")
        w("")

    w(f"## Tier 3: service-specific metrics (`{SERVICE_PREFIX}*`)")
    w("")
    w("| Metric | Type | Labels | Meaning |")
    w("|---|---|---|---|")
    for name in sorted(n for n in scrape if n.startswith(SERVICE_PREFIX)):
        fam = scrape[name]
        labels = ", ".join(f"`{label}`" for label in sorted(fam["labels"])) or "-"
        w(f"| `{name}` | {fam.get('type', '')} | {labels} | {md(fam.get('help'))} |")
    w("")
    print("\n".join(out))


if __name__ == "__main__":
    main()
